update country_flag_history set label_fr = 'Révolution grecque (1821-1830)', label_en = 'Greek Revolution (1821–1830)', notes_fr = 'Pendant la guerre d''indépendance, les insurgés adoptent la croix blanche sur fond bleu, couleurs fixées par l''Assemblée d''Épidaure en janvier 1822.', notes_en = 'During the War of Independence the insurgents took up the white cross on blue, colours set by the Assembly of Epidaurus in January 1822.' where id = 2379 and iso_code = 'gr';
